package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static ge.opensoft.openservice.WorkflowSupport.auth;
import java.util.*;
final class BulkChangesAcceptance {
 static final String API="/api/openservice/bulk/incident";
 static Map<String,Object> result(java.net.http.HttpResponse<byte[]> r,int status){return CatalogueQuestionsAcceptance.result(r,status);}
 static Map<String,Object> review(Object records,Object patch){return map("operation","review","records",records,"patch",patch);}
 static Map<String,Object> apply(Map<String,Object> input,Map<String,Object> reviewed){var body=new LinkedHashMap<>(input);body.putAll(map("operation","apply","proof",object(reviewed.get("review")).get("proof"),"key",id(),"confirm",true));return body;}
 static Map<String,Object> post(WorkflowSupport h,Object body,String user,int status)throws Exception{return result(h.json("POST",API,body,auth(user)),status);}
 static Map<String,Object> prepare(WorkflowSupport h,Map<String,Object> body,String user)throws Exception{return apply(body,post(h,body,user,200));}
 static List<String> seed(WorkflowSupport h)throws Exception{h.account("BulkAgent","agent");h.account("BulkReader","reader");return List.of(h.add("incident").get("sys_id").toString(),h.add("incident").get("sys_id").toString());}
 static Map<String,Object> record(WorkflowSupport h,String id)throws Exception{return result(h.get("/api/now/table/incident/"+id,auth("admin")),200);}
 static void run(WorkflowSupport h)throws Exception{
  var ids=seed(h);for(String id:ids)assertEquals(200,h.json("POST",RecordCollaborationAcceptance.route(id),RecordCollaborationAcceptance.subscription(0,List.of("changes")),auth("BulkReader")).statusCode());var before=record(h,ids.getFirst());var request=review(ids,map("description","Reviewed bulk <script>escaped</script>","priority","2","state","2"));long events;try(var db=h.store.open()){events=db.count("SELECT COUNT(*) FROM os_event");PlatformFoundationTest.bind(db);EventWorkflows.save(db,"",EventWorkflowsAcceptance.config(0,"entered","2",List.of(EventWorkflowsAcceptance.note())));db.connection.commit();}var input=prepare(h,request,"BulkAgent");assertEquals(before,record(h,ids.getFirst()));try(var db=h.store.open()){assertEquals(events,db.count("SELECT COUNT(*) FROM os_event"));assertEquals(0,db.count("SELECT COUNT(*) FROM os_notice"));assertEquals(0,db.count("SELECT COUNT(*) FROM os_bulk_receipt"));assertEquals(0,db.count("SELECT COUNT(*) FROM os_event_run"));}var receipt=object(post(h,input,"BulkAgent",200).get("receipt"));assertEquals(receipt,post(h,input,"BulkAgent",200).get("receipt"));for(String id:ids){assertEquals("2",record(h,id).get("priority"));assertEquals("1",record(h,id).get("sys_mod_count"));}try(var db=h.store.open()){assertEquals(events+2,db.count("SELECT COUNT(*) FROM os_event"));assertEquals(2,db.count("SELECT COUNT(*) FROM os_notice"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_bulk_receipt"));assertEquals(2,db.count("SELECT COUNT(*) FROM os_event_run"));}new Store(h.environment);assertEquals(receipt,object(result(h.get(API+"/"+input.get("key"),auth("BulkAgent")),200).get("receipt")));assertEquals(404,h.get(API+"/"+input.get("key"),auth("admin")).statusCode());assertEquals(405,h.json("POST",API+"/"+input.get("key"),input,auth("BulkAgent")).statusCode());input.put("patch",map("priority","3"));assertEquals(409,h.json("POST",API,input,auth("BulkAgent")).statusCode());
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  var ids=seed(h);assertEquals(401,h.get(API,null).statusCode());assertEquals(403,h.get(API,auth("BulkReader")).statusCode());assertEquals(403,h.json("POST",API,review(ids,map("priority","2")),auth("BulkReader")).statusCode());assertEquals(400,h.get(API+"?q=x",auth("admin")).statusCode());assertEquals(405,h.json("PUT",API,map(),auth("admin")).statusCode());assertEquals(404,h.get("/api/openservice/bulk/unknown",auth("admin")).statusCode());assertEquals(404,h.get(API+"/"+id(),auth("admin")).statusCode());assertEquals(403,h.form("/bulk/incident",map(),auth("admin")).statusCode());
  for(var input:List.of(map(),map("operation","invalid"),review("scalar",map("priority","2")),review(List.of(),map("priority","2")),review(Collections.nCopies(21,ids.getFirst()),map("priority","2")),review(List.of(ids.getFirst(),ids.getFirst()),map("priority","2")),review(List.of(1),map("priority","2")),review(List.of("invalid"),map("priority","2")),review(ids,"scalar"),review(ids,map()),review(ids,map("unknown","x"))))assertEquals(400,h.json("POST",API,input,auth("admin")).statusCode());var fields=map();for(int n=0;n<11;n++)fields.put("field"+n,"x");assertEquals(400,h.json("POST",API,review(ids,fields),auth("admin")).statusCode());var extra=review(ids,map("priority","2"));extra.put("extra",true);assertEquals(400,h.json("POST",API,extra,auth("admin")).statusCode());assertEquals(404,h.json("POST",API,review(List.of(id()),map("priority","2")),auth("admin")).statusCode());String foreign=h.add("problem").get("sys_id").toString();assertEquals(404,h.json("POST",API,review(List.of(foreign),map("priority","2")),auth("admin")).statusCode());
  var good=prepare(h,review(ids,map("priority","2")),"admin");for(var patch:List.of(map("confirm",false),map("key","bad"),map("proof","bad"),map("extra",1))){var body=new LinkedHashMap<>(good);body.putAll(patch);assertEquals(400,h.json("POST",API,body,auth("admin")).statusCode());}assertEquals(400,h.protectedForm("/bulk/incident",map("operation","review","selected_"+ids.getFirst(),"false","patch","{}"),auth("admin")).statusCode());assertEquals(400,h.protectedForm("/bulk/incident",map("operation","review","records","[","patch","{}"),auth("admin")).statusCode());assertEquals(200,h.protectedForm("/bulk/incident",map("operation","review","records",JSON.writeValueAsString(ids),"patch","{\"priority\":\"2\"}"),auth("admin")).statusCode());
 }
 static void staleAndAuthority(WorkflowSupport h)throws Exception{
  var ids=seed(h);var request=review(ids,map("priority","2"));var input=prepare(h,request,"BulkAgent");RecordCollaborationAcceptance.change(h,ids.getFirst(),"changed after review");assertEquals(409,h.json("POST",API,input,auth("BulkAgent")).statusCode());assertEquals("0",record(h,ids.getLast()).get("sys_mod_count"));input=prepare(h,request,"BulkAgent");try(var db=h.store.open()){db.update("UPDATE os_user SET auth_revision=auth_revision+1 WHERE name='BulkAgent'");db.connection.commit();}assertEquals(409,h.json("POST",API,input,auth("BulkAgent")).statusCode());input=prepare(h,request,"BulkAgent");Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"incident");}var schema=new LinkedHashMap<>(original);schema.put("label","Incident schema changed");ReferencePickerAcceptance.writeSchema(h,"incident",schema);assertEquals(409,h.json("POST",API,input,auth("BulkAgent")).statusCode());ReferencePickerAcceptance.writeSchema(h,"incident",original);
  input=prepare(h,request,"BulkAgent");ProblemInvestigationsAcceptance.access(h,"incident",ids.getLast(),"private",FieldDispatchAcceptance.uid(h,"admin"));assertEquals(404,h.json("POST",API,input,auth("BulkAgent")).statusCode());ProblemInvestigationsAcceptance.access(h,"incident",ids.getLast(),"workspace","");input=prepare(h,request,"BulkAgent");post(h,input,"BulkAgent",200);schema=new LinkedHashMap<>(original);schema.put("field_rules",map("priority",map("type","string","read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"incident",schema);assertEquals(403,h.get(API+"/"+input.get("key"),auth("BulkAgent")).statusCode());assertEquals(403,h.json("POST",API,request,auth("BulkAgent")).statusCode());ReferencePickerAcceptance.writeSchema(h,"incident",original);schema=new LinkedHashMap<>(original);schema.put("record_roles",map("update",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"incident",schema);assertEquals(403,h.get(API,auth("BulkAgent")).statusCode());ReferencePickerAcceptance.writeSchema(h,"incident",original);schema=new LinkedHashMap<>(original);schema.put("field_rules",map("priority",map("type","string","write_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"incident",schema);assertEquals(403,h.json("POST",API,review(ids,map("priority","3")),auth("BulkAgent")).statusCode());ReferencePickerAcceptance.writeSchema(h,"incident",original);
  schema=new LinkedHashMap<>(original);schema.put("field_rules",map("number",map("type","string","read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"incident",schema);var protectedReceipt=object(result(h.get(API+"/"+input.get("key"),auth("BulkAgent")),200).get("receipt"));assertEquals(ids.getFirst(),objects(object(object(protectedReceipt.get("detail")).get("review")).get("changes")).getFirst().get("label"));ReferencePickerAcceptance.writeSchema(h,"incident",original);
  String parent=h.add("incident").get("sys_id").toString();try(var db=h.store.open()){db.update("INSERT INTO os_record_scope(record_id,parent_id,revision) VALUES(?,?,1)",ids.getLast(),parent);db.connection.commit();}ProblemInvestigationsAcceptance.access(h,"incident",parent,"private",FieldDispatchAcceptance.uid(h,"admin"));assertEquals(404,h.get(API+"/"+input.get("key"),auth("BulkAgent")).statusCode());
 }
 static void nativeRulesAndRollback(WorkflowSupport h)throws Exception{
  var ids=seed(h);assertEquals(200,h.json("PATCH","/api/now/table/incident/"+ids.getLast(),map("state","2"),auth("admin")).statusCode());var first=record(h,ids.getFirst());var last=record(h,ids.getLast());assertEquals(409,h.json("POST",API,review(ids.reversed(),map("state","3")),auth("admin")).statusCode());assertEquals(first,record(h,ids.getFirst()));assertEquals(last,record(h,ids.getLast()));assertEquals(400,h.json("POST",API,review(ids,map("priority","invalid")),auth("admin")).statusCode());var input=prepare(h,review(ids,map("description","Atomic final")),"admin");post(h,input,"admin",200);var failure=prepare(h,review(ids,map("description","Must roll back")),"admin");try(var db=h.store.open()){db.update("CREATE UNIQUE INDEX fixture_bulk_failure ON os_bulk_receipt(actor_id)");db.connection.commit();}first=record(h,ids.getFirst());last=record(h,ids.getLast());assertEquals(500,h.json("POST",API,failure,auth("admin")).statusCode());assertEquals(first,record(h,ids.getFirst()));assertEquals(last,record(h,ids.getLast()));try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_bulk_receipt"));db.update("DROP INDEX fixture_bulk_failure");db.connection.commit();}post(h,failure,"admin",200);
 }
 static void concurrency(WorkflowSupport h)throws Exception{
  var ids=seed(h);var input=prepare(h,review(ids,map("description","Once concurrently")),"BulkAgent");try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var first=pool.submit(()->post(h,input,"BulkAgent",200));var second=pool.submit(()->post(h,input,"BulkAgent",200));assertEquals(first.get().get("receipt"),second.get().get("receipt"));}for(String id:ids)assertEquals("1",record(h,id).get("sys_mod_count"));assertEquals(204,h.json("DELETE","/api/now/table/incident/"+ids.getFirst(),map(),auth("admin")).statusCode());assertEquals(404,h.get(API+"/"+input.get("key"),auth("BulkAgent")).statusCode());
 }
 static void limits(WorkflowSupport h)throws Exception{
  var ids=new ArrayList<>(seed(h));try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(int n=0;n<18;n++)ids.add(Service.create(db,"incident",map("short_description","Bulk boundary"),"admin").get("sys_id").toString());db.connection.commit();}var input=prepare(h,review(ids,map("priority","2")),"admin");post(h,input,"admin",200);try(var db=h.store.open()){String actor=RecordAccess.owner(db,"admin");for(int n=0;n<99;n++)db.update("INSERT INTO os_bulk_receipt(actor_id,request_key,table_name,fingerprint,created,detail) VALUES(?,?,?,?,?,?)",actor,id(),"incident","fixture",now(),"{}");db.connection.commit();}var more=prepare(h,review(ids,map("priority","3")),"admin");assertEquals(400,h.json("POST",API,more,auth("admin")).statusCode());assertEquals(200,h.json("POST",API,input,auth("admin")).statusCode());try(var db=h.store.open()){String other=RecordAccess.owner(db,"BulkReader");for(int n=0;n<4900;n++)db.update("INSERT INTO os_bulk_receipt(actor_id,request_key,table_name,fingerprint,created,detail) VALUES(?,?,?,?,?,?)",other,id(),"incident","fixture",now(),"{}");db.connection.commit();}more=prepare(h,review(ids,map("priority","3")),"BulkAgent");assertEquals(400,h.json("POST",API,more,auth("BulkAgent")).statusCode());
 }
}
